mapper.select:
SELECT examiner_id
FROM session_examiners
WHERE session_id = #{sessionId}

mapper.delete:
DELETE FROM session_examiners
WHERE session_id = #{sessionId}
  AND examiner_id = #{examinerId}

mapper.select:
SELECT COUNT(1)
FROM session_examiners se
         JOIN slot_sessions ss ON ss.session_id = se.session_id
WHERE ss.assignment_id = #{assignmentId}
  AND se.examiner_id = #{examinerId}
